<script>
  import { tick } from 'svelte';
  import { inspect, preview, merge, extract, rotate, annotate, savePdf } from './lib/pdf.js';
  let files=[], index=0, info=null, canvas, page=1, task='extract', range='1', angle=90, annotation='', x=40,y=650,size=16, busy=false, error='', success='';
  $: active=files[index];
  async function choose(i){index=i;page=1;info=null;error='';success='';try{info=await inspect(files[i]);range=`1-${info.pages}`;await tick();await render();}catch(e){error=`Unable to open PDF: ${e.message}`;}}
  async function render(){if(active&&info&&canvas)try{await preview(active,page,canvas);}catch(e){error=`Preview failed: ${e.message}`;}}
  async function add(event){const items=Array.from(event.currentTarget.files||[]).filter(f=>/\.pdf$/i.test(f.name));if(!items.length)return;const first=files.length;files=[...files,...items];await choose(first);event.currentTarget.value='';}
  function remove(i){files=files.filter((_,j)=>j!==i);info=null;if(files.length)void choose(Math.min(i,files.length-1));else{index=0;error='';success='';}}
  async function change(delta){page=Math.min(info.pages,Math.max(1,page+delta));await render();}
  async function exportPdf(){busy=true;error='';success='';try{let result;if(task==='merge')result=await merge(files);if(task==='extract')result=await extract(active,range);if(task==='rotate')result=await rotate(active,range,Number(angle));if(task==='text')result=await annotate(active,page,annotation,x,y,size);savePdf(result,active.name.replace(/\.pdf$/i,'')+'-'+task+'.pdf');success='PDF exported locally. Your original file was not modified.';}catch(e){error=e.message;}finally{busy=false;}}
  async function copyHash(){await navigator.clipboard.writeText(info.hash);success='SHA-256 copied to clipboard.';}
</script>
<svelte:head><meta name="description" content="CipherPDF — a local-first, open source PDF editor"/></svelte:head>
<div class="app">
<aside class="sidebar"><div class="brand"><span class="logo">◈</span><div><strong>CipherPDF</strong><small>PRIVATE PDF WORKSPACE</small></div></div><div class="muted caption">WORKSPACE</div><div class="nav">▣ &nbsp; PDF Studio</div><div class="muted caption">DOCUMENTS · {files.length}</div><div class="filelist">{#each files as file,i}<div class:current={index===i} class="file"><button on:click={()=>choose(i)} title={file.name}>▤ &nbsp; {file.name}</button><button class="close" aria-label="Remove PDF" on:click={()=>remove(i)}>×</button></div>{/each}</div><label class="add" for="picker">+ Add documents</label><div class="sidebarbottom"><b>●</b> Processing stays in your browser<small>No server-side document uploads</small></div></aside>
<main><header><span>Workspace <span class="muted">/</span> <b>PDF Studio</b></span><div><span class="pill">● Local-first</span><a href="https://github.com/saadaltafofficial/cipherpdf" target="_blank" rel="noreferrer">GitHub ↗</a></div></header>
<section class="body"><div class="heading"><div><small class="eyebrow">DOCUMENT WORKSPACE / V0.2</small><h1>PDF Studio</h1><p>Preview, arrange and edit PDFs entirely on your device.</p></div><label class="primary" for="picker">+ Open PDFs</label></div><input id="picker" type="file" multiple accept=".pdf,application/pdf" hidden on:change={add}/>
{#if error}<div class="message err" role="alert">{error}</div>{/if}{#if success}<div class="message ok" role="status">{success}</div>{/if}
{#if !active}<label for="picker" class="empty"><div>▧</div><h2>Your private PDF workspace</h2><p>Select one or more PDF files to get started.</p><span class="primary">Browse local files</span><small>Files remain on this device. No account required.</small></label>{:else}
<div class="workspace"><div class="panel"><div class="panelhead"><div><b>{active.name}</b><small>{info?`${info.pages} pages · ${(info.bytes/1024).toFixed(1)} KB`:'Opening…'}</small></div><span class="muted">PREVIEW</span></div><div class="paper">{#if info}<canvas bind:this={canvas} aria-label="PDF preview"></canvas>{:else}<p>Loading PDF…</p>{/if}</div><div class="pager"><button disabled={!info||page<=1} on:click={()=>change(-1)}>←</button><span>Page {page} of {info?.pages||'—'}</span><button disabled={!info||page>=info.pages} on:click={()=>change(1)}>→</button></div></div>
<div class="right"><div class="panel tool"><div class="panelhead"><div><b>Document tools</b><small>Local operations · export as PDF</small></div></div><div class="tabs"><button class:chosen={task==='extract'} on:click={()=>task='extract'}>Extract</button><button class:chosen={task==='rotate'} on:click={()=>task='rotate'}>Rotate</button><button class:chosen={task==='merge'} on:click={()=>task='merge'}>Merge</button><button class:chosen={task==='text'} on:click={()=>task='text'}>Add text</button></div>
{#if task==='extract'||task==='rotate'}<label for="range">Page range</label><input id="range" bind:value={range}/><small>Example: 1,3-5</small>{/if}
{#if task==='rotate'}<label for="angle">Angle</label><select id="angle" bind:value={angle}><option value={90}>90° clockwise</option><option value={180}>180°</option><option value={270}>270° clockwise</option></select>{/if}
{#if task==='merge'}<p>All {files.length} open documents are merged in sidebar order. Add at least two.</p>{/if}
{#if task==='text'}<label for="annotation">Text on page {page}</label><textarea id="annotation" bind:value={annotation} rows="3" placeholder="Type your text"></textarea><div class="coords"><label>X<input type="number" min="0" bind:value={x}/></label><label>Y<input type="number" min="0" bind:value={y}/></label><label>Size<input type="number" min="8" max="72" bind:value={size}/></label></div><small>Coordinates measured from page bottom-left. This inserts text; it does not replace existing text.</small>{/if}
<button class="export" disabled={busy||!info} on:click={exportPdf}>{busy?'Processing…':'Export PDF ↓'}</button></div>
<div class="panel hashpanel"><div class="panelhead"><div><b>Document fingerprint</b><small>SHA-256 of original file bytes</small></div></div>{#if info}<div class="hash">{info.hash}</div><button class="copy" on:click={copyHash}>Copy fingerprint</button>{/if}<p>A hash only detects changes against a trusted reference. It is not a digital signature or proof of signer identity.</p></div></div></div>{/if}
</section><footer>Apache-2.0 · Open source <span>Certificate signing, PAdES verification and encryption are not implemented yet.</span></footer></main></div>
